<?php
namespace App\Services\Marketing;
use App\Services\Marketing\Audience\{AudienceDirectory,AudienceSegments};
use Illuminate\Support\Facades\{DB,Crypt};
use Illuminate\Support\Str;
use App\Domain\Marketing\MarketingPermission as P;
final class MarketingEmailBatches {
 private function rows(int $u,string $campaign){app(MarketingCampaigns::class)->query($u)->findOrFail($campaign);return DB::table('marketing_email_batches')->where('merchant_key',app(AudienceDirectory::class)->merchant())->where('user_id',$u)->where('campaign_id',$campaign);}
 public function listing(int $u,string $campaign):array{return $this->rows($u,$campaign)->latest()->limit(20)->get()->map(fn($b)=>$this->view($b))->all();}
 public function view($b):array {$p=json_decode(Crypt::decryptString($b->payload),true);$ids=array_column($p['recipients'],'delivery_id');$q=DB::table('marketing_email_deliveries')->where('merchant_key',$b->merchant_key)->whereIn('id',$ids);$counts=(clone $q)->selectRaw('state, COUNT(*) as n')->groupBy('state')->pluck('n','state')->all();return ['id'=>$b->id,'state'=>$b->state,'total'=>$b->total,'excluded'=>$b->excluded,'processed'=>$b->cursor,'counts'=>$counts,'error_code'=>$b->error_code,'currency'=>$p['currency'],'cost_limit_minor'=>$p['cost_limit_minor'],'sender'=>$p['from_address'],'expires_at'=>$b->expires_at,'created_at'=>$b->created_at,'feedback_connected'=>false,'records'=>(clone $q)->latest()->limit(50)->get()->map(function($r){$email=Crypt::decryptString($r->recipient);[$n,$d]=explode('@',$email,2);return ['id'=>$r->id,'recipient'=>mb_substr($n,0,2).'***@'.$d,'state'=>$r->state,'error_code'=>$r->error_code,'accepted_at'=>$r->accepted_at];})->all()];}
 private function sender():void {abort_unless(config('mail.default')==='smtp'&&filter_var(app(MarketingEmailSettings::class)->from()['address'],FILTER_VALIDATE_EMAIL),409,'Configure and verify the store email sender first.');}
 private function price():?int {return app(MarketingEmailSettings::class)->price();}
 public function review(int $u,string $id,array $d):array {
  $this->sender();$url=parse_url($d['landing_url']);$origin=parse_url(config('app.url'));abort_unless(filter_var($d['landing_url'],FILTER_VALIDATE_URL)&&in_array($url['scheme']??'',['http','https'],true)&&!isset($url['user'])&&!isset($url['pass'])&&strtolower($url['host']??'')===strtolower($origin['host']??'')&&($url['port']??($url['scheme']==='https'?443:80))===($origin['port']??($origin['scheme']==='https'?443:80)),422,'Choose a landing page on this store.');
  return DB::transaction(function()use($u,$id,$d){$c=app(MarketingCampaigns::class)->query($u)->lockForUpdate()->findOrFail($id);abort_unless($c->channel==='email'&&$c->status==='Draft'&&$c->version===$d['version'],409,'Save and reload the Email Campaign draft first.');$old=$this->rows($u,$id)->where('campaign_version',$c->version)->first();if($old){$p=json_decode(Crypt::decryptString($old->payload),true);abort_unless($p['landing_url']===$d['landing_url'],409,'This saved review uses another landing page. Save a new campaign version to change it.');return $this->view($old);}
  $doc=$c->channel_document;$t=app(MarketingContentTemplates::class)->query($u)->where('channel','email')->whereNull('archived_at')->find($doc['template_id']??null);$s=DB::table('marketing_audience_segments')->where('merchant_key',$c->merchant_key)->whereNull('archived_at')->where('status','active')->find($doc['segment_id']??null);abort_unless($t&&$s&&$t->version===($doc['template_version']??null)&&$s->version===($doc['segment_version']??null),409,'Save the selected template and segment again before reviewing.');
  $rules=app(AudienceSegments::class);$q=$rules->apply(app(AudienceDirectory::class)->query(),json_decode($s->rules,true));$matched=(clone $q)->count();$eligible=$rules->eligible(clone $q,'email')->orderBy('id')->limit(1001)->get();abort_if($eligible->count()>1000,422,'This release supports up to 1,000 eligible contacts per campaign. Choose a smaller segment.');$recipients=[];foreach($eligible as $contact){$email=mb_strtolower(trim($contact->email));if(!filter_var($email,FILTER_VALIDATE_EMAIL)||app(MarketingEmailUnsubscribe::class)->suppressed($c->merchant_key,$email))continue;$hash=hash_hmac('sha256',$email,config('app.key'));if(DB::table('marketing_email_deliveries')->where('campaign_id',$id)->where('campaign_version',$c->version)->where('recipient_hash',$hash)->exists())continue;$recipients[$hash]=['email'=>$email,'name'=>$contact->name,'contact_id'=>$contact->id,'delivery_id'=>(string)Str::uuid(),'hash'=>$hash];}abort_unless(count($recipients),422,'No eligible subscribed contacts are available.');$subject=$doc['subject']??$t->document['subject']??'';abort_unless(trim($subject)!=='',422,'Add an email subject.');$unit=$this->price();$payload=['recipients'=>array_values($recipients),'template_id'=>$t->id,'template_version'=>$t->version,'segment_id'=>$s->id,'segment_version'=>$s->version,'subject'=>$subject,'html'=>$t->document['content_html']??'<p>'.e($t->document['body']??'').'</p>','landing_url'=>$d['landing_url'],'from_address'=>app(MarketingEmailSettings::class)->from()['address'],'from_name'=>app(MarketingEmailSettings::class)->from()['name'],'currency'=>app(MarketingEmailSettings::class)->currency(),'settings_version'=>app(MarketingEmailSettings::class)->version(),'unit_minor'=>$unit,'cost_limit_minor'=>$unit===null?null:$unit*count($recipients)];
  $batch=(string)Str::uuid();DB::table('marketing_email_batches')->insert(['id'=>$batch,'campaign_id'=>$id,'merchant_key'=>$c->merchant_key,'user_id'=>$u,'campaign_version'=>$c->version,'digest'=>hash('sha256',json_encode($payload,JSON_THROW_ON_ERROR)),'state'=>'review','total'=>count($recipients),'excluded'=>$matched-count($recipients),'cursor'=>0,'payload'=>Crypt::encryptString(json_encode($payload,JSON_THROW_ON_ERROR)),'expires_at'=>now()->addDay(),'created_at'=>now(),'updated_at'=>now()]);return $this->view($this->rows($u,$id)->find($batch));});
 }
 public function confirm(int $u,string $campaign,string $id,array $d):array {return DB::transaction(function()use($u,$campaign,$id,$d){$c=app(MarketingCampaigns::class)->query($u)->lockForUpdate()->findOrFail($campaign);$b=$this->rows($u,$campaign)->lockForUpdate()->find($id);abort_unless($b,404);$p=json_decode(Crypt::decryptString($b->payload),true);if($b->confirmed_at)return $this->view($b);abort_unless($b->state==='review'&&$c->version===$d['version']&&$b->campaign_version===$c->version&&$c->status==='Draft'&&now()->lt($b->expires_at),409,'This review has expired or changed. Review the saved campaign again.');$this->sender();$t=app(MarketingContentTemplates::class)->query($u)->whereNull('archived_at')->find($p['template_id']);$s=DB::table('marketing_audience_segments')->where('merchant_key',$b->merchant_key)->whereNull('archived_at')->where('status','active')->find($p['segment_id']);abort_unless($t&&$s&&$t->version===$p['template_version']&&$s->version===$p['segment_version'],409,'The template or segment changed. Save and review a new campaign version.');abort_unless(config('marketing.email_bulk_enabled',false)&&app(MarketingEmailSettings::class)->ready($p['settings_version']??0)&&$p['cost_limit_minor']!==null&&$this->price()===$p['unit_minor']&&$d['cost_limit_minor']===$p['cost_limit_minor']&&$p['currency']===app(MarketingEmailSettings::class)->currency()&&$p['from_address']===app(MarketingEmailSettings::class)->from()['address'],409,'Sending is paused until the sender and delivery cost are confirmed.');DB::table('marketing_email_batches')->where('id',$id)->update(['state'=>'queued','confirmed_at'=>now(),'updated_at'=>now()]);\App\Jobs\SendMarketingEmailBatch::dispatch($id)->afterCommit();return $this->view($this->rows($u,$campaign)->find($id));});}
 private function allowed($b):bool{return config('marketing.email_bulk_enabled',false)&&$b->merchant_key===app(AudienceDirectory::class)->merchant()&&P::allows(\App\Models\User::find($b->user_id),P::MANAGE_CAMPAIGNS)&&P::allows(\App\Models\User::find($b->user_id),P::VIEW_AUDIENCE);}
 public function run(string $id):void {
  $b=DB::transaction(function()use($id){$b=DB::table('marketing_email_batches')->where('id',$id)->lockForUpdate()->first();if(!$b||$b->state!=='queued')return null;if(!$this->allowed($b)){DB::table('marketing_email_batches')->where('id',$id)->update(['state'=>'paused','error_code'=>'sending_unavailable','updated_at'=>now()]);return null;}DB::table('marketing_email_batches')->where('id',$id)->update(['state'=>'processing','updated_at'=>now()]);return $b;});if(!$b)return;
  $p=json_decode(Crypt::decryptString($b->payload),true,512,JSON_THROW_ON_ERROR);if(!app(MarketingEmailSettings::class)->ready($p['settings_version']??0)||$p['unit_minor']!==$this->price()||$p['currency']!==app(MarketingEmailSettings::class)->currency()||$p['from_address']!==app(MarketingEmailSettings::class)->from()['address']){$this->pause($id,'sender_or_cost_changed');return;}try{foreach(array_slice($p['recipients'],$b->cursor,25) as $recipient){if(!$this->allowed($b)||!app(MarketingEmailSettings::class)->ready($p['settings_version']??0)||$p['unit_minor']!==$this->price()||$p['currency']!==app(MarketingEmailSettings::class)->currency()||$p['from_address']!==app(MarketingEmailSettings::class)->from()['address']){$this->pause($id,'sending_unavailable');return;}$this->prepareRecipient($b,$p,$recipient);app(MarketingEmailDelivery::class)->run($recipient['delivery_id']);$state=DB::table('marketing_email_deliveries')->where('id',$recipient['delivery_id'])->value('state');if($state==='queued'&&DB::table('marketing_email_deliveries')->where('id',$recipient['delivery_id'])->value('error_code')==='rate_limited'){DB::table('marketing_email_batches')->where('id',$id)->update(['state'=>'queued','error_code'=>'rate_limited','updated_at'=>now()]);\App\Jobs\SendMarketingEmailBatch::dispatch($id)->delay(now()->addMinute());return;}if(in_array($state,['unknown','sending','queued'],true)){$this->pause($id,'submission_unconfirmed');return;}DB::table('marketing_email_batches')->where('id',$id)->increment('cursor',1,['updated_at'=>now()]);}$fresh=DB::table('marketing_email_batches')->find($id);$done=$fresh->cursor>=$fresh->total;DB::table('marketing_email_batches')->where('id',$id)->update(['state'=>$done?'completed':'queued','updated_at'=>now()]);if(!$done)\App\Jobs\SendMarketingEmailBatch::dispatch($id);}catch(\Throwable){$this->pause($id,'processing_interrupted');}
 }
 private function prepareRecipient($b,array $p,array $r):void {DB::transaction(function()use($b,$p,$r){app(MarketingEmailUnsubscribe::class)->lock($b->merchant_key);if(DB::table('marketing_email_deliveries')->where('id',$r['delivery_id'])->exists())return;$link=(string)Str::uuid();$tracking=url('/m/r/'.$link);$unsubscribe=app(MarketingEmailUnsubscribe::class)->link($r['delivery_id'],$b->merchant_key);$parts=explode(' ',trim($r['name']),2);$values=['{{first_name}}'=>$parts[0]?:'Customer','{{last_name}}'=>$parts[1]??'','{{email}}'=>$r['email'],'{{store_name}}'=>app(\App\Support\ShopBrand::class)->name(),'{{unsubscribe_url}}'=>$unsubscribe];$html=strtr($p['html'],array_map(fn($v)=>e($v),$values));$dom=new \DOMDocument();$old=libxml_use_internal_errors(true);$dom->loadHTML('<?xml encoding="utf-8" ?>'.$html);libxml_clear_errors();libxml_use_internal_errors($old);$linked=false;foreach($dom->getElementsByTagName('a') as $a){if($a->getAttribute('href')===$unsubscribe||str_contains(strtolower($a->textContent),'unsubscribe')||$a->getAttribute('href')==='#')continue;$a->setAttribute('href',$tracking);$linked=true;break;}$html=$dom->saveHTML();if(!$linked)$html.='<p><a href="'.e($tracking).'">Visit website</a></p>';$html.='<p><a href="'.e($unsubscribe).'">Unsubscribe from marketing emails</a></p>';$snapshot=['kind'=>'bulk','settings_version'=>$p['settings_version'],'reply_to'=>app(MarketingEmailSettings::class)->raw()['reply_to']??null,'batch_id'=>$b->id,'contact_id'=>$r['contact_id'],'subject'=>strtr($p['subject'],$values),'html'=>$html,'template_id'=>$p['template_id'],'template_version'=>$p['template_version'],'unsubscribe_url'=>$unsubscribe,'from_address'=>$p['from_address'],'from_name'=>$p['from_name']];DB::table('marketing_tracking_links')->insert(['id'=>$link,'campaign_id'=>$b->campaign_id,'post_id'=>null,'channel'=>'email','destination_id'=>$r['delivery_id'],'merchant_key'=>$b->merchant_key,'user_id'=>$b->user_id,'post_version'=>$b->campaign_version,'destination_url'=>$p['landing_url'],'created_at'=>now(),'updated_at'=>now()]);DB::table('marketing_email_deliveries')->insert(['id'=>$r['delivery_id'],'campaign_id'=>$b->campaign_id,'user_id'=>$b->user_id,'merchant_key'=>$b->merchant_key,'campaign_version'=>$b->campaign_version,'recipient'=>Crypt::encryptString($r['email']),'recipient_hash'=>$r['hash'],'state'=>'queued','link_id'=>$link,'snapshot'=>json_encode($snapshot,JSON_THROW_ON_ERROR),'created_at'=>now(),'updated_at'=>now()]);});}
 public function pause(string $id,string $code='processing_interrupted'):void {$b=DB::table('marketing_email_batches')->find($id);if($b){$p=json_decode(Crypt::decryptString($b->payload),true);DB::table('marketing_email_deliveries')->where('merchant_key',$b->merchant_key)->whereIn('id',array_column($p['recipients'],'delivery_id'))->where('state','sending')->update(['state'=>'unknown','error_code'=>'submission_unconfirmed','updated_at'=>now()]);}DB::table('marketing_email_batches')->where('id',$id)->whereIn('state',['queued','processing'])->update(['state'=>'paused','error_code'=>$code,'updated_at'=>now()]);}
}
